<script setup>
import { ref, computed } from 'vue';
import OperatorPerusahaanLayout from '@/Layouts/OperatorPerusahaanLayout.vue';
import { Head, Link } from '@inertiajs/vue3';

defineOptions({ layout: OperatorPerusahaanLayout });

const insentifs = ref([
  { id: 1, nama: 'Kolektor - Tunai 5%', tipe_insentif: 'persentase', nominal: 5, status: 'Aktif', deskripsi: 'Insentif 5% dari nominal pembayaran tunai.', created_at: '2025-01-01' },
  { id: 2, nama: 'Kolektor - Transfer 3%', tipe_insentif: 'persentase', nominal: 3, status: 'Aktif', deskripsi: 'Insentif 3% dari nominal pembayaran transfer.', created_at: '2025-01-01' },
  { id: 3, nama: 'Bonus Tunggakan 10%', tipe_insentif: 'persentase', nominal: 10, status: 'Aktif', deskripsi: 'Bonus tambahan 10% untuk tagihan lewat jatuh tempo.', created_at: '2025-02-01' },
  { id: 4, nama: 'Insentif Admin - Tetap', tipe_insentif: 'statis', nominal: 50000, status: 'Nonaktif', deskripsi: 'Insentif tetap Rp50.000/bulan untuk admin.', created_at: '2025-03-01' },
]);

const searchInput = ref(''); const search = ref(''); const statusFilter = ref(''); const currentPage = ref(1); const perPage = ref(5); const perPageOptions = [5, 10, 25, 50, 100];
const selectedIds = ref([]); const selectAll = ref(false); const sortFields = ref([]); const selectedItem = ref(null);
const showCreateModal = ref(false); const showDetailModal = ref(false); const showEditModal = ref(false); const showDeleteModal = ref(false);
const form = ref({ id: null, nama: '', tipe_insentif: 'persentase', nominal: '', status: 'Aktif', deskripsi: '' }); const formErrors = ref({}); const nextId = ref(5);

function applySearch() { search.value = searchInput.value; currentPage.value = 1; } function clearSearch() { searchInput.value = ''; search.value = ''; currentPage.value = 1; } function applyStatusFilter(s) { statusFilter.value = s; currentPage.value = 1; } function changePerPage(n) { perPage.value = n; currentPage.value = 1; }
function toggleSelectAll() { selectedIds.value = selectAll.value ? paginatedInsentifs.value.map(i => i.id) : []; }
function toggleSelect(id) { const i = selectedIds.value.indexOf(id); i === -1 ? selectedIds.value.push(id) : selectedIds.value.splice(i, 1); selectAll.value = selectedIds.value.length === paginatedInsentifs.value.length; }
function bulkDelete() { insentifs.value = insentifs.value.filter(i => !selectedIds.value.includes(i.id)); selectedIds.value = []; selectAll.value = false; } function bulkSetStatus(s) { insentifs.value.forEach(i => { if (selectedIds.value.includes(i.id)) i.status = s; }); selectedIds.value = []; selectAll.value = false; }
function sort(field) { const e = sortFields.value.findIndex(s => s.field === field); if (e !== -1) { if (sortFields.value[e].dir === 'asc') sortFields.value[e].dir = 'desc'; else sortFields.value.splice(e, 1); } else sortFields.value.push({ field, dir: 'asc' }); }
function sortIcon(f) { const s = sortFields.value.find(s => s.field === f); if (!s) return 'fa-sort'; return s.dir === 'asc' ? 'fa-sort-up' : 'fa-sort-down'; } function sortOrder(f) { const i = sortFields.value.findIndex(s => s.field === f); return i !== -1 ? i + 1 : null; }
function statusBadge(s) { return s === 'Aktif' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400'; }
function tipeBadge(t) { return t === 'persentase' ? 'bg-sky-100 text-sky-700 dark:bg-sky-900/30 dark:text-sky-400' : 'bg-violet-100 text-violet-700 dark:bg-violet-900/30 dark:text-violet-400'; }
function formatNominal(i) { return i.tipe_insentif === 'persentase' ? i.nominal + '%' : 'Rp ' + Number(i.nominal).toLocaleString('id-ID'); }

const filteredInsentifs = computed(() => {
  let r = [...insentifs.value]; if (search.value) { const q = search.value.toLowerCase(); r = r.filter(x => x.nama.toLowerCase().includes(q)); }
  if (statusFilter.value) r = r.filter(x => x.status === statusFilter.value); if (sortFields.value.length > 0) r.sort((a, b) => { for (const s of sortFields.value) { const av = a[s.field], bv = b[s.field]; if (av != bv) return (typeof av === 'string' ? av.localeCompare(bv) : av - bv) * (s.dir === 'asc' ? 1 : -1); } return 0; }); return r;
});
const totalPages = computed(() => Math.ceil(filteredInsentifs.value.length / perPage.value) || 1);
const paginatedInsentifs = computed(() => { const s = (currentPage.value - 1) * perPage.value; return filteredInsentifs.value.slice(s, s + perPage.value); });
const visiblePages = computed(() => { const p = []; const t = totalPages.value; const c = currentPage.value; let st = Math.max(1, c - 2); let en = Math.min(t, c + 2); if (en - st < 4) { if (st === 1) en = Math.min(t, st + 4); else st = Math.max(1, en - 4); } for (let i = st; i <= en; i++) p.push(i); return p; });

function openCreate() { form.value = { id: null, nama: '', tipe_insentif: 'persentase', nominal: '', status: 'Aktif', deskripsi: '' }; formErrors.value = {}; showCreateModal.value = true; }
function openDetail(i) { selectedItem.value = i; showDetailModal.value = true; } function openEdit(i) { form.value = { ...i }; formErrors.value = {}; showEditModal.value = true; } function openDelete(i) { selectedItem.value = i; showDeleteModal.value = true; }
function validateForm() { const e = {}; if (!form.value.nama.trim()) e.nama = 'Nama insentif wajib diisi'; if (form.value.nominal === '' || Number(form.value.nominal) < 0) e.nominal = 'Nominal tidak valid'; formErrors.value = e; return Object.keys(e).length === 0; }
function saveCreate() { if (!validateForm()) return; insentifs.value.unshift({ id: nextId.value++, ...form.value, nominal: Number(form.value.nominal), created_at: new Date().toISOString().split('T')[0] }); showCreateModal.value = false; }
function saveEdit() { if (!validateForm()) return; const i = insentifs.value.findIndex(x => x.id === form.value.id); if (i !== -1) insentifs.value[i] = { ...insentifs.value[i], ...form.value, nominal: Number(form.value.nominal) }; showEditModal.value = false; }
function confirmDelete() { insentifs.value = insentifs.value.filter(i => i.id !== selectedItem.value.id); showDeleteModal.value = false; if (paginatedInsentifs.value.length === 0 && currentPage.value > 1) currentPage.value--; } function goToPage(p) { currentPage.value = Math.max(1, Math.min(p, totalPages.value)); }
</script>

